import json, os, subprocess, sys, shutil
from pathlib import Path
sys.path.insert(0, "/home/usain/gov-os-worktrees/W2-37/tests/acceptance/W2-37")
import w2_37_support as S

TMP = Path(os.environ["TMPDIR"])
BOX = S.make_box(TMP / "box")


def g(root, *argv, json_=True):
    args = ["impact"] + (["--json"] if json_ else []) + ["--root", str(root)] + list(argv)
    run = S.gov(BOX, *args)
    if not json_:
        return run.returncode, run.stdout, run.stderr
    try:
        env = json.loads(run.stdout)
    except Exception:
        return run.returncode, {"raw": run.stdout, "err": run.stderr[-800:]}
    return run.returncode, env


def fresh(name, code=False):
    root = TMP / "repos" / name
    if root.exists():
        shutil.rmtree(root)
    S.build_fixture(root, code=code)
    S.load_store(root, BOX)
    return S.Project.__new__(S.Project), root


def project(root):
    p = S.Project.__new__(S.Project)
    p.root, p.minute = Path(root), 100
    return p


def brief(env):
    if not isinstance(env, dict) or "result" not in env:
        return env
    r = env["result"]
    if "change" in r and isinstance(r["change"], list):
        return {"change": [(c["id"], c["graph"], c["deletable"]) for c in r["change"]], "radius": r["radius"],
                "depth": r["depth"], "src": r.get("depth_source"), "graphs": r["graphs"], "complete": r["complete"],
                "affected": {k: [i["id"] for i in v] for k, v in r["affected"].items() if v},
                "gaps": r["gaps"][:6]}
    return r
